import psutil
import ctypes
import time

def get_windows_processes():
    """
    Returns a list of running windows processes.
    """
    processes = []
    for proc in psutil.process_iter():
        try:
            if proc.name() and proc.name() != "csrss.exe" and proc.name() != "System":
                processes.append(proc)
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            pass
    return processes

def close_application(pid):
    """
    Closes an application by its process ID.
    """
    try:
        ctypes.windll.user32.SendMessageW(
            int(pid),
            0x11,
            0x0001,
            0x0000
        )
    except Exception as e:
        print(f"Error closing application with PID {pid}: {e}")

def close_all_applications():
    """
    Closes all running applications.
    """
    processes = get_windows_processes()
    for process in processes:
        try:
            close_application(process.pid)
        except Exception as e:
            print(f"Error closing application with PID {process.pid}: {e}")

if __name__ == "__main__":
    close_all_applications()
